import {esc,fmt} from './tank-visuals.js';
import {nozzleLocationModel,nozzleDirectionLabel,clusterNozzleMarkers} from './tank-nozzle-position.js';
import {nozzleHasConflict} from './tank-nozzles.js';
import {nozzleBuilderSummary} from './tank-nozzle-builder.js';
import {flangeIcon} from './tank-flanges.js';
const safe=(value,min,max)=>Math.max(min,Math.min(max,value));
export function nozzleLocationMarkup(r,{selected,editing=false,cluster=[],view='body'}={}){
  const m=nozzleLocationModel(r,selected);if(!m)return '<p class="tank-note">選一個管嘴，就能看它的位置。</p>';
  const {n,horizontal,host,parallel,body,end}=m,mark=n.mark||n.id,name=n.mark&&n.name?.startsWith(n.mark+' · ')?n.name.slice(n.mark.length+3):n.name;
  const built=nozzleBuilderSummary(n,r);
  const focus=(field,label,value)=>`<button type="button" data-nozzle-focus="${field}" aria-label="修改${esc(label)}">${esc(value)} <span aria-hidden="true">✎</span></button>`;
  const surface=(kind,label)=>editing&&m.solved?`data-nozzle-position="${kind}" role="button" tabindex="0" aria-label="${esc(label)}"`:'';
  function markers(items,highlight=null){const placed=[];return clusterNozzleMarkers(items).map(g=>{
    let x=g.x,y=g.y;const moved=highlight&&Math.hypot(x-highlight.x,y-highlight.y)<38;
    if(moved){x+=x<260?52:-52;y+=y<132?30:-30;}
    const maxY=items===m.bodyMarkers?190:225,base={x,y},candidates=[[0,0],[0,44],[0,-44],[44,0],[-44,0],[44,44],[-44,44],[0,88],[44,-44],[-44,-44]];
    for(const [dx,dy] of candidates){const candidate={x:base.x+dx,y:base.y+dy};if(candidate.x<100||candidate.x>440||candidate.y<38||candidate.y>maxY)continue;if(highlight&&Math.hypot(candidate.x-highlight.x,candidate.y-highlight.y)<38)continue;if(placed.some(p=>Math.hypot(p.x-candidate.x,p.y-candidate.y)<42))continue;x=candidate.x;y=candidate.y;break;}placed.push({x,y});
    return `${x!==g.x||y!==g.y?`<path d="M${g.x} ${g.y}L${x} ${y}" stroke="#a5b9ae" stroke-dasharray="3 3" pointer-events="none"/>`:''}<g class="nozzle-map-other" ${editing?'pointer-events="none" aria-hidden="true" opacity=".45"':g.items.length>1?`data-nozzle-cluster="${g.items.map(p=>p.id).join('|')}" role="button" tabindex="0" aria-label="這裡有 ${g.items.length} 個管嘴，展開選擇"`:`data-nozzle-select="${g.items[0].id}" role="button" tabindex="0" aria-label="選取 ${esc(g.items[0].mark+' '+g.items[0].name)}"`}><title>${esc(g.items.map(p=>p.mark+' '+p.name).join('、'))}</title><circle cx="${x}" cy="${y}" r="21" fill="transparent"/><circle cx="${x}" cy="${y}" r="${g.items.length>1?12:6}" fill="#dbe6e0" stroke="#93aaa0" stroke-width="1.5"/>${g.items.length>1?`<text x="${x}" y="${y+4}" text-anchor="middle" fill="#486b5e" font-size="12" font-weight="700" pointer-events="none">${g.items.length}</text>`:''}</g>`;
  }).join('');}
  const dot=(x,y)=>`<g pointer-events="none"><circle cx="${x}" cy="${y}" r="15" fill="#fff" opacity=".9"/><circle cx="${x}" cy="${y}" r="9" fill="#c58a35" stroke="#fff" stroke-width="2"/></g>`;
  let side,sideLabel,sideValue,sideNote;
  if(horizontal){
    const x=m.bodyPoint===null?null:safe(m.bodyPoint,body.start,body.end),head=host==='bottom'?44:476;
    side=`<svg viewBox="0 0 520 215" role="group" aria-label="側視：A端在左、B端在右，橘色是目前管嘴的軸向位置"><path d="M80 62C25 62 25 130 80 130H440C495 130 495 62 440 62Z" fill="#edf3ef" stroke="#769c8e" stroke-width="2"/><rect x="80" y="62" width="360" height="68" fill="#e0eee7" stroke="#769c8e" stroke-width="1.5" ${host==='shell'?surface('height','點筒身調整距A端板邊的距離'):''}/><path d="M80 49V166M440 49V166" stroke="#9fb5ab" stroke-dasharray="4 4" pointer-events="none"/><path d="M29 96H491" stroke="#c3d4ca" stroke-dasharray="5 5" pointer-events="none"/><text x="28" y="36" fill="#446b5b" font-size="16" font-weight="700">A端</text><text x="462" y="36" fill="#446b5b" font-size="16" font-weight="700">B端</text>${markers(m.bodyMarkers,host==='shell'&&m.bodyPoint!==null?{x:horizontal?m.bodyPoint:body.axis,y:horizontal?body.axis:m.bodyPoint}:null)}${host==='shell'&&x!==null?`<path d="M${x} 57V137" stroke="#c58a35" stroke-width="5" opacity=".7" pointer-events="none"/>${dot(x,96)}<path d="M80 153H${x}M80 146V160M${x} 146V160" fill="none" stroke="#b47a2a" stroke-width="2" pointer-events="none"/>`:host!=='shell'?dot(head,96):''}<text x="80" y="181" fill="#557466" font-size="12">筒身板邊 0</text><text x="440" y="181" text-anchor="end" fill="#557466" font-size="12">筒身板邊 ${fmt(r.bodyHeight)}</text><text x="260" y="205" text-anchor="middle" fill="#85988d" font-size="11">只看沿槽身距離；圓周方向見下圖 · 非比例</text></svg>`;
    sideLabel=host==='shell'?'沿槽身，離 A 端多遠？':`裝在 ${host==='bottom'?'A':'B'} 端封頭`;
    sideValue=host==='shell'?focus('height','距A端筒身板邊',m.height===null?'待填':fmt(m.height)+' mm'):'<span class="nozzle-map-fixed">端部已選定</span>';
    sideNote=host==='shell'?(m.datumShift>0&&m.tlDistance!==null?`從 A 端筒身板邊量 ${fmt(m.height)} mm。若原圖從 A 端 TL 量，是 ${fmt(m.tlDistance)} mm（差 ${fmt(m.datumShift)} mm）。`:'從左邊的 A 端筒身板邊起量，往 B 端增加。'):'封頭管嘴不使用筒身板邊距離；改看下圖的中心偏心與方向。';
  }else{
    const y=m.bodyPoint===null?null:safe(m.bodyPoint,55,190),head=host==='top'?34:210;
    side=`<svg viewBox="0 0 520 250" role="group" aria-label="立式槽側視：由筒身板下緣往上量"><path d="M205 55C205 15 315 15 315 55V190C315 224 205 224 205 190Z" fill="#edf3ef" stroke="#769c8e" stroke-width="2"/><rect x="205" y="55" width="110" height="135" fill="#e0eee7" stroke="#769c8e" stroke-width="1.5" ${host==='shell'?surface('height','點筒身調整距下緣的高度'):''}/><path d="M260 23V224" stroke="#c3d4ca" stroke-dasharray="5 5" pointer-events="none"/><text x="335" y="59" fill="#557466" font-size="12">筒身板上緣</text><text x="335" y="194" fill="#557466" font-size="12">下緣 0 mm</text>${markers(m.bodyMarkers,host==='shell'&&m.bodyPoint!==null?{x:horizontal?m.bodyPoint:body.axis,y:horizontal?body.axis:m.bodyPoint}:null)}${host==='shell'&&y!==null?`<path d="M200 ${y}H320" stroke="#c58a35" stroke-width="5" opacity=".7" pointer-events="none"/>${dot(260,y)}<path d="M174 190V${y}M167 190H181M167 ${y}H181" fill="none" stroke="#b47a2a" stroke-width="2" pointer-events="none"/>`:host!=='shell'?dot(260,head):''}<text x="260" y="243" text-anchor="middle" fill="#85988d" font-size="11">由下往上量；圓周方向見下圖 · 非比例</text></svg>`;
    sideLabel=host==='shell'?'沿槽身，離下緣多高？':`裝在${host==='top'?'上':'下'}端`;
    sideValue=host==='shell'?focus('height','距筒身板下緣',m.height===null?'待填':fmt(m.height)+' mm'):'<span class="nozzle-map-fixed">端部已選定</span>';
    sideNote=host==='shell'?`從筒身板下緣往上量；筒身板高 ${fmt(r.bodyHeight)} mm。`:'端部管嘴的位置，由端板中心往外量偏心。';
  }
  const opening=m.endPoint,angle=m.angle===null?'待填':fmt(m.angle)+'°',direction=m.angle===null?'方向待填':nozzleDirectionLabel(m.angle,horizontal);
  const sx=opening?.x??end.cx,sy=opening?.y??end.cy;
  const tubeHalf=safe(Number(n.od)/r.od*84,3,7),flangeHalf=safe(Number(n.flangeOD)/r.od*84,tubeHalf+2,14),extension=safe(Number(n.projection)/15,10,18);
  const fitting=Number.isFinite(tubeHalf+flangeHalf+extension)?`<g transform="translate(${sx} ${sy}) rotate(${(m.angle??0)-90})" pointer-events="none"><rect x="0" y="${-tubeHalf}" width="${extension}" height="${tubeHalf*2}" fill="#aacbbb" stroke="#54816a" stroke-width="1.3"/>${n.end!=='bare'?`<rect x="${extension-2}" y="${-flangeHalf}" width="4" height="${flangeHalf*2}" rx="1" fill="#d7bc91" stroke="#aa854f" stroke-width="1.2"/>`:''}</g>`:'';
  const clock=`<svg viewBox="75 0 370 267" role="group" aria-label="${horizontal?'站在 A 端面向 B 端，看圓周方向':'從槽頂往下看，順時針為正角度'}"><circle cx="260" cy="132" r="84" fill="#eff5f1" stroke="#719789" stroke-width="2" ${surface(host==='shell'?'angle':'end',parallel?'點圖調整橫向偏心；管軸方向保持不變':host==='shell'?'點圓周調整方位角':'點端面調整偏心與方位')}/><path d="M260 48V216M176 132H344" stroke="#becfc5" stroke-dasharray="4 4" pointer-events="none"/><text x="260" y="25" text-anchor="middle" fill="#557466" font-size="13">${horizontal?'上方':'基準'} 0°</text><text x="390" y="137" fill="#557466" font-size="13">右 90°</text><text x="260" y="256" text-anchor="middle" fill="#557466" font-size="13">${horizontal?'下方':'對側'} 180°</text><text x="130" y="137" text-anchor="end" fill="#557466" font-size="13">左 270°</text>${markers(m.endMarkers,m.endPoint)}${opening?`<path d="M260 132L${sx} ${sy}" stroke="#c58a35" stroke-width="1.5" stroke-dasharray="4 3" pointer-events="none"/>${host==='shell'?fitting:''}${dot(sx,sy)}`:''}</svg>`;
  const circleValue=parallel?focus('offset','管軸橫向偏心',m.offset===null?'偏心待填':'偏心 '+fmt(m.offset)+' mm'):host==='shell'?focus('angle','方位角',direction+' '+angle):focus('radius','距端板中心偏心',m.radius===null?'偏心待填':'偏心 '+fmt(m.radius)+' mm');
  const circleNote=parallel?`管軸朝向 ${angle}；橘點是開孔位置${m.surfaceAngle===null?'':'（'+fmt(m.surfaceAngle,1)+'°）'}。偏心會移動開孔，並不等於改變管軸角度。`:host==='shell'?`${horizontal?'站在 A 端，面向 B 端':'站在槽頂往下看'}；${horizontal?'0°在上、90°在右，順時針增加。':'以0°為基準，順時針增加。'}`:`由端板中心量偏心 ${m.radius===null?'待填':fmt(m.radius)+' mm'}，方位 ${angle}。${horizontal?'統一由 A 端看，B 端也沿用同一套方向。':'由上往下看，順時針增加。'}`;
  const choices=cluster.map(id=>r.input.nozzles.find(n=>n.id===id)).filter(Boolean);
  const hasIssue=m.solved&&nozzleHasConflict(n);
  return `<div class="nozzle-location-focus" data-nozzle-location-selected="${esc(n.id)}"><header class="nozzle-map-heading"><div><span class="nozzle-map-selected-tag">${esc(mark)}</span><strong>${esc(name||'目前管嘴')}</strong></div><button type="button" data-nozzle-map-edit aria-pressed="${editing}"${m.solved?'':' disabled'}>${editing?'完成調整':'調整圖上位置'}</button></header><button type="button" class="nozzle-map-build-summary" data-nozzle-build aria-label="在這個位置編輯管嘴尺寸與接法">${flangeIcon(n.end)}<span><strong>${esc(built.size)}</strong><small>外伸 ${esc(built.projection)} · ${esc(built.end)}</small></span><span aria-hidden="true">↗</span></button><p class="nozzle-map-key"><span></span>橘色是目前管嘴；灰點可切換，數字表示同區有多個。</p><nav class="nozzle-map-views" aria-label="管嘴位置的兩個方向"><button type="button" data-nozzle-location-view="body" aria-pressed="${view==='body'}">① 沿槽身的位置<small>${host==='shell'?(m.height===null?'距離待填':fmt(m.height)+' mm'):(horizontal?(host==='bottom'?'A端封頭':'B端封頭'):(host==='bottom'?'下端':'上端'))}</small></button><button type="button" data-nozzle-location-view="end" aria-pressed="${view==='end'}">② 圓周方向<small>${parallel?'偏心 '+fmt(m.offset)+' mm':host==='shell'?direction+' '+angle:'偏心 '+fmt(m.radius)+' mm'}</small></button></nav>${editing?'<p class="nozzle-map-edit-note">現在可以點圖改位置；點數字可精確輸入。方向鍵微調，Shift加快。</p>':''}${!m.solved?'<p class="nozzle-map-edit-note">此管嘴資料待修正；圖面只協助定位，不表示開孔已通過檢查。</p>':''}<figure class="nozzle-map-figure"${view==='body'?'':' hidden'}><figcaption><span>1</span><strong>${sideLabel}</strong>${sideValue}</figcaption>${side}<p>${esc(sideNote)}</p></figure><figure class="nozzle-map-figure"${view==='end'?'':' hidden'}><figcaption><span>2</span><strong>${horizontal?'從 A 端看，裝在哪一面？':'從上往下看，圓周哪一面？'}</strong>${circleValue}</figcaption>${clock}<p>${esc(circleNote)}${host==='shell'?' 管嘴外形為辨識示意。':''}</p>${parallel||host!=='shell'?`<div class="nozzle-map-secondary">${focus('angle',host==='shell'?'管軸方位':'偏心方位',`${host==='shell'?'管軸方向':'偏心方位'} ${angle}`)}</div>`:''}</figure>${choices.length?`<section class="nozzle-map-choices" aria-label="同區管嘴"><strong>這個位置有 ${choices.length} 個管嘴，選一個看清楚</strong><div>${choices.map(p=>`<button type="button" data-nozzle-select="${p.id}">${esc(p.mark||p.id)}<small>${esc(p.name)}</small></button>`).join('')}</div></section>`:''}${hasIssue?`<p class="nozzle-map-conflict">${esc(mark)} 有尺寸或接合問題，位置示意不代表可施工。<button type="button" data-nozzle-issue="${n.id}" data-field="host">查看目前管嘴 →</button></p>`:''}</div>`;
}
